<template>
  <div class="sidebar">
    <div>
      <h1>MAFE TESLIM</h1>
    </div>
    <nav>
      <ul>
        <li>
          <a
            href="#"
            :class="{ active: activeSection === 'hero' }"
            @click.prevent="scrollToSection('hero')"
            >Home</a
          >
        </li>
        <li>
          <a
            href="#"
            :class="{ active: activeSection === 'gallery' }"
            @click.prevent="scrollToSection('gallery')"
            >Gallery</a
          >
        </li>
        <li>
          <a
            href="#"
            :class="{ active: activeSection === 'contact' }"
            @click.prevent="scrollToSection('contact')"
            >Contact</a
          >
        </li>
      </ul>
    </nav>
  </div>
</template>

<script>
import { ref, onMounted, onBeforeUnmount } from "vue";

export default {
  setup() {
    const activeSection = ref("hero"); // Initially active section

    const scrollToSection = (sectionId) => {
      const element = document.getElementById(sectionId);
      if (element) {
        element.scrollIntoView({
          behavior: "smooth",
          block: "start",
        });
        activeSection.value = sectionId; // Highlight the clicked section immediately
      }
    };

    const handleScroll = () => {
      const sections = ["hero", "gallery", "contact"];

      let closestSection = null;
      let minDistance = Infinity;

      for (const section of sections) {
        const element = document.getElementById(section);
        if (element) {
          const rect = element.getBoundingClientRect();
          const windowHeight =
            window.innerHeight || document.documentElement.clientHeight; // Compatibility
          const distance = Math.abs(rect.top - windowHeight / 2); // Distance from element's top to the center of the screen

          if (distance < minDistance) {
            minDistance = distance;
            closestSection = section;
          }
        }
      }

      if (closestSection) {
        activeSection.value = closestSection;
      }
    };

    onMounted(() => {
      window.addEventListener("scroll", handleScroll);
      handleScroll(); // Initial check on mount
    });

    onBeforeUnmount(() => {
      window.removeEventListener("scroll", handleScroll);
    });

    return {
      activeSection,
      scrollToSection,
    };
  },
};
</script>

<style scoped>
.sidebar {
  width: 300px;
  background-color: #111;
  color: white;
  padding: 20px;
  height: 100vh;
  position: sticky;
  top: 0;
}

.sidebar h1 {
  margin-top: 1rem;
  font-size: 50px;
  letter-spacing: 3px;
}

nav ul {
  list-style: none;
  padding: 0;
}
nav {
  margin-top: 3rem;
}

nav a {
  display: block;
  padding: 10px;
  color: #555;
  text-decoration: none;
}
nav a:hover {
  color: #777;
  transform: scale(1.05);
  transition: all ease-in-out 0.3s;
}

nav a.active {
  font-weight: bold;
  color: red;
  font-size: 30px;
  transition: all ease-in-out 0.4s;
}

/* ////////////////////////////////////////////////////// */
/* RESPONSIVE STYLES
  /////////////////////////////// */
@media (max-width: 768px) {
  .sidebar {
    display: none;
  }
}
</style>
