<template>
  <div class="gallery-container">
    <!-- Category Selection Bar -->
    <div class="category-bar">
      <button
        v-for="category in categories"
        :key="category.name"
        :class="{ active: selectedCategory === category.name }"
        @click="selectCategory(category.name)"
      >
        {{ category.name }}
      </button>
    </div>

    <!-- Image Grid -->
    <div class="image-grid">
      <div
        v-for="(project, index) in currentCategoryProjects"
        :key="index"
        class="image-item"
        @click="openFullscreen(project)"
      >
        <img :src="project.images[0].src" :alt="project.name" />
      </div>
    </div>

    <!-- Fullscreen Project View -->
    <div
      v-if="showFullscreen"
      class="fullscreen-overlay"
      @click.self="closeFullscreen"
    >
      <button class="close-button" @click="closeFullscreen">X</button>

      <div class="fullscreen-content">
        <!-- Project Images -->
        <div class="fullscreen-images">
          <button class="nav-button prev" @click="prevImage"><</button>
          <img
            :src="selectedProject.images[currentImageIndex].src"
            :alt="selectedProject.name"
            class="fullscreen-image"
            @click.stop="zoomImage"
          />
          <button class="nav-button next" @click="nextImage">></button>
        </div>

        <!-- Project Description and Link -->
        <div class="project-details">
          <h2>{{ selectedProject.name }}</h2>
          <p class="fullscreen-description">
            {{ selectedProject.description }}
          </p>
          <a
            :href="selectedProject.googleDriveLink"
            target="_blank"
            class="google-drive-link"
          >
            Project Documents (Google Drive)
          </a>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
