                alt: "Project 2 - Image 1",
              },
              {
                src: require("@/assets/images/image6.jpeg"),
                alt: "Project 2 - Image 2",
              },
              {
                src: require("@/assets/images/image7.jpeg"),
                alt: "Project 2 - Image 3",
              },
            ],
          },
          {
            name: "Project 3",
            description: "Project 3 description",
            googleDriveLink:
              "https://drive.google.com/drive/folders/your-folder-id",
            images: [
              {
                src: require("@/assets/images/image8.jpeg"),
                alt: "Project 3 - Image 1",
              },
              {
                src: require("@/assets/images/image9.jpg"),
                alt: "Project 3 - Image 2",
              },
              {
                src: require("@/assets/images/image10.jpeg"),
                alt: "Project 3 - Image 3",
              },
            ],
          },
          {
            name: "Project 4",
            description: "Project 4 description",
            googleDriveLink:
              "https://drive.google.com/drive/folders/your-folder-id",
            images: [
              {
                src: require("@/assets/images/image11.jpeg"),
                alt: "Project 4 - Image 1",
              },
              {
                src: require("@/assets/images/image12.jpeg"),
                alt: "Project 4 - Image 2",
              },
            ],
          },
        ],
      },
      {
        name: "Logos",
        projects: [
          {
            name: "Project 1",
            description: "Project 1 description",
            googleDriveLink:
              "https://drive.google.com/drive/folders/your-folder-id",
            images: [
              {
                src: require("@/assets/images/image13.jpg"),
                alt: "Project 1 - Image 1",
              },
              {
