                alt: "Project 1 - Image 2",
              },
            ],
          },
          {
            name: "Project 2",
            description: "Project 2 description",
            googleDriveLink:
              "https://drive.google.com/drive/folders/your-folder-id",
            images: [
              {
                src: require("@/assets/images/image5.jpg"),
                alt: "Project 2 - Image 1",
              },
              {
                src: require("@/assets/images/image6.jpeg"),
                alt: "Project 2 - Image 2",
              },
            ],
          },
        ],
      },
    ]);

    const selectedCategory = ref(categories.value[0].name); // Initial category
    const selectedProject = ref(null);
    const showFullscreen = ref(false);
    const currentImageIndex = ref(0); // Track the current image index in the fullscreen view

    const currentCategoryProjects = ref(categories.value[0].projects);

    // Function to select a category and update the projects
    const selectCategory = (categoryName) => {
      selectedCategory.value = categoryName;
      currentCategoryProjects.value = categories.value.find(
        (cat) => cat.name === categoryName
      ).projects;
    };

    // Function to open the fullscreen view with the selected project
    const openFullscreen = (project) => {
      selectedProject.value = project;
      showFullscreen.value = true;
      currentImageIndex.value = 0; // Reset the current image index
    };

    // Function to close the fullscreen view
    const closeFullscreen = () => {
      showFullscreen.value = false;
    };

    // Function to navigate to the next image in the project
    const nextImage = () => {
      currentImageIndex.value =
        (currentImageIndex.value + 1) % selectedProject.value.images.length;
    };

    // Function to navigate to the previous image in the project
    const prevImage = () => {
      currentImageIndex.value =
        (currentImageIndex.value - 1 + selectedProject.value.images.length) %
        selectedProject.value.images.length;
    };

    // Function to zoom in the image (to be implemented later)
    const zoomImage = () => {};

    // Add event listener for keyboard navigation
    onMounted(() => {
      document.addEventListener("keydown", handleArrowKeys);
    });

    // Function to handle keyboard navigation (arrow keys)
    const handleArrowKeys = (event) => {
      if (showFullscreen.value) {
        if (event.key === "ArrowRight") {
          nextImage();
        } else if (event.key === "ArrowLeft") {
          prevImage();
        }
      }
    };

    return {
      categories,
      selectedCategory,
      selectedProject,
      showFullscreen,
      currentCategoryProjects,
      currentImageIndex,
      selectCategory,
      openFullscreen,
      closeFullscreen,
      nextImage,
      prevImage,
      zoomImage,
    };
  },
};
</script>

<style scoped>
/* :root {
  --gallery-image-height: 200px;
} */

.gallery-container {
  padding-top: 3rem;
  height: 100%; /* Changed from 100vh */
  width: 100%;
  padding-left: 1rem;
  padding-right: 1rem;
  box-sizing: border-box;
  background-color: #111;
}

/* Category Bar */
.category-bar {
  display: flex;
  justify-content: center;
  margin-bottom: 20px;
}

.category-bar button {
  background-color: #555;
  border: none;
  padding: 10px 20px;
  margin: 0 5px;
  cursor: pointer;
  border-radius: 5px;
  transition: background-color 0.3s ease;
}

.category-bar button.active {
  background-color: red;
  color: white;
}
.category-bar button:hover {
  background-color: #777;
  transform: scale(1.05);
}

/* Image Grid */
.image-grid {
  display: grid;
  grid-template-columns: repeat(
    auto-fit,
    minmax(300px, 1fr)
  ); /* Enforce 3+ images per column */
  gap: 20px;
  /* height: calc(
    100% - 60px
  );  */
  /* subtracts the top 60px from the bottom part of the display so that its all within view.*/
  width: 100%;
  overflow: auto;
}

.image-item {
  cursor: pointer;
  border-radius: 5px;
  overflow: hidden;
  transition: transform 0.3s ease;
}

.image-item:hover {
  transform: scale(1.05);
}

.image-item img {
  width: 100%;
  /* height: var(--gallery-image-height); */
  height: 200px;
  object-fit: cover;
  display: block;
}

/* Fullscreen Overlay */
.fullscreen-overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(0, 0, 0, 0.9);
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 1000;
}

.fullscreen-content {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.fullscreen-images {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  max-width: 800px; /* Adjust max width as needed */
}

.close-button {
  position: absolute;
  top: 20px;
  right: 20px;
  background-color: transparent;
  border: none;
  color: white;
  font-size: 2em;
  cursor: pointer;
  transition: color 0.3s ease;
}

.close-button:hover {
  color: red;
}

.nav-button {
  background-color: transparent;
  border: 2px solid red;
  border-radius: 50%;
  color: white;
  font-size: 2em;
  height: 80px;
  width: 80px;
  cursor: pointer;
  transition: background-color 0.3s ease;
  position: absolute;
  top: 60%;
  transform: translateY(-50%);
}
.nav-button:hover {
  border: 2px solid #555;
  color: red;
  transition: all ease-in-out 0.5s;
}

.nav-button.prev {
  left: -200px;
}

.nav-button.next {
  right: -200px;
}

.fullscreen-image {
  max-width: 80%;
  max-height: 70vh;
  border-radius: 5px;
  cursor: pointer;
}

.fullscreen-description {
  color: white;
  font-size: 1.2em;
  /* margin-left: 4rem; */
  text-align: center;
}

.google-drive-link {
  display: inline-block;
  margin-top: 20px;
  padding: 10px 20px;
  background-color: red;
  color: white;
  text-decoration: none;
  border-radius: 5px;
}
.google-drive-link:hover {
  background-color: #111;
  border: 2px solid #111;
  color: #555;
  transition: all ease-in-out 0.5s;
}

.project-details {
  text-align: center;
  color: white;
  width: 100%;
  padding: 20px;
  box-sizing: border-box;
}

/* Responsive Design */
@media (max-width: 768px) {
  .image-grid {
    grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  }

  .fullscreen-image {
    max-width: 95%;
    max-height: 60vh;
  }

  .nav-button {
    width: 50px;
    height: 50px;
    font-size: 1.5em;
  }

  .nav-button.prev {
    left: 10px;
  }

  .nav-button.next {
    right: 10px;
  }

  .nav-button {
   display: none;
  }
}
</style>
