<template>
  <div class="hero-section">
    <div class="image-slider">
      <img
        :src="images[currentImageIndex]"
        alt="Hero Image"
        class="slide"
        :class="{ 'slide-enter': imageTransitioning }"
      />
    </div>
    <div id="initials">
      <div class="initials"><p>M.T</p></div>
      <div class="initials-name">
        <p>
          MAFE
          <br />
          TESLIM
        </p>
      </div>
    </div>
    <div class="text-content">
      <h1>What I Do</h1>
      <div class="changing-text">
        <h2 :class="{ 'text-enter': textTransitioning }">
          {{ texts[currentTextIndex].title }}
        </h2>
        <p :class="{ 'text-enter': textTransitioning }">
          {{ texts[currentTextIndex].content }}
        </p>
      </div>
    </div>

    <div class="flex justify-center mt-10">
      <div class="animate-bounce">
        <svg
          id="one"
          xmlns="http://www.w3.org/2000/svg"
          class="h-8 w-8 text-gray-500"
          fill="none"
          viewBox="0 0 24 24"
          stroke="currentColor"
        >
          <path
            stroke-linecap="round"
            stroke-linejoin="round"
            stroke-width="2"
            d="M19 9l-7 7-7-7"
          />
        </svg>
        <svg
          xmlns="http://www.w3.org/2000/svg"
          class="h-8 w-8 text-gray-500"
          fill="none"
          viewBox="0 0 24 24"
          stroke="currentColor"
        >
          <path
            stroke-linecap="round"
            stroke-linejoin="round"
            stroke-width="2"
            d="M19 9l-7 7-7-7"
          />
        </svg>
      </div>
    </div>
  </div>
</template>

<script>
import { ref, onMounted, nextTick } from "vue";

export default {
  setup() {
    const images = ref([
      require("@/assets/images/image1.jpg"), // Replace with your image paths
      require("@/assets/images/image2.jpg"),
      require("@/assets/images/image3.jpg"),
    ]);

    const texts = ref([
      {
        title: "Visual Strategist",
        content:
          " Understands brand values, target audience, and competition to create a logo that effectively communicates the brand's essence and differentiates it in the market.",
      },
      {
        title: "Visual Communicator",
        content:
          "Uses typography, color, shape, and imagery to convey a specific message or feeling, creating a cohesive and memorable logo that reflects the brand's personality.",
      },
      {
        title: "Problem Solver",
        content:
          "Creates versatile, scalable, and memorable logos that work across various platforms, navigating client feedback and technical challenges to deliver a successful visual identity.",
      },
    ]);

    const currentImageIndex = ref(0);
    const currentTextIndex = ref(0);
    const imageTransitioning = ref(false);
    const textTransitioning = ref(false);

    const transitionDuration = 1000; // 1 second

    onMounted(() => {
      // Image Transition
      setInterval(() => {
        imageTransitioning.value = true; // Trigger transition
        setTimeout(() => {
          currentImageIndex.value =
            (currentImageIndex.value + 1) % images.value.length;
          imageTransitioning.value = false;
        }, transitionDuration); // Wait for transition, then update index
      }, 6000); // Change image every 6 seconds

      // Text Transition
      setInterval(() => {
        textTransitioning.value = true;
        setTimeout(() => {
          currentTextIndex.value =
            (currentTextIndex.value + 1) % texts.value.length;
          textTransitioning.value = false;
        }, transitionDuration);
      }, 8000); // Change text every 8 seconds
    });

    return {
      images,
      texts,
      currentImageIndex,
      currentTextIndex,
      imageTransitioning,
      textTransitioning,
    };
  },
};
</script>

